// `pipe` exactly as `@solid-primitives/utils@7.0.0-next.4` declares it
// (`dist/index.d.ts`); `pipeOpen` is its control, the same declaration with
// the contract's `callbacks` left open.
//
// The signatures are `tsc`-clean for every call `App.tsx` makes, so nothing
// here duplicates a type diagnostic.
export declare function pipe<A, B>(a: (raw: string) => A, b: (a: A) => B): (raw: string) => B;
export declare function pipeOpen<A, B>(a: (raw: string) => A, b: (a: A) => B): (raw: string) => B;
